// Com alwaysOutputData, uma lista vazia chega como um item vazio; ele não é viagem.
return [
  {
    json: {
      trips: $input.all().map(item => item.json).filter(trip => trip && trip.title)
    }
  }
];

// ===== CONFIGURAÇÃO (edite apenas aqui) =====
// (A regra de retorno do assistente fica na query do node "Consulta estado do atendimento": 12h após a última mensagem da equipe, ou 72h se a equipe nunca respondeu)
// Horas até o assistente voltar quando NINGUÉM da equipe respondeu (use o mesmo valor da query do node "Consulta estado do atendimento")
const HORAS_SEM_RESPOSTA = 72;
// ChatId da equipe que recebe o aviso (grupo "xxxxx@g.us" ou número "55DDDNUMERO@c.us")
const EQUIPE_CHAT_ID = '__TEAM_GROUP_ID__@g.us';

// Mensagens enviadas ao cliente quando a conversa é transferida (sem o Gemini)
const TEXTOS = {
  midia: 'Recebi o seu arquivo! Vou avisar a nossa equipe de atendimento para analisar, e você receberá o retorno em breve, tudo bem?',
  pagamento: 'Obrigado pelo aviso! Se ainda não enviou o comprovante, pode mandar por aqui mesmo. Em breve nossa equipe irá conferir o pagamento e prosseguir com seu atendimento, tudo bem?',
  cartao: 'Sobre o cartão: podem existir taxas ou juros da operadora. Em breve nossa equipe irá prosseguir com seu atendimento, tudo bem?',
  pedido_do_cliente: 'Claro! Em breve nossa equipe irá prosseguir com seu atendimento, tudo bem?',
  reclamacao: 'Sinto muito por isso. Em breve nossa equipe irá prosseguir com seu atendimento para resolver isso com você, tudo bem?',
  sem_resposta: 'Essa eu prefiro confirmar com o time para te responder com segurança. Em breve nossa equipe irá prosseguir com seu atendimento, tudo bem?',
  // Falha técnica: o assistente NÃO é pausado (a equipe só é avisada); por isso o texto pede para o cliente tentar de novo
  falha: 'Desculpe, tive um problema para responder agora. Já avisei a nossa equipe. Se puder, envie sua mensagem de novo daqui a pouco, tudo bem?',
  outro: 'Em breve nossa equipe irá prosseguir com seu atendimento, tudo bem?'
};
// Usado quando o modelo repete uma anotação interna do histórico (ex.: "[mídia recebida]") em vez de responder
const TEXTO_SEM_MIDIA = 'Por aqui eu consigo ler mensagens de texto e entender áudios. Figurinhas, imagens e vídeos eu não consigo ver, mas se for algo importante é só me avisar que eu chamo a nossa equipe.';
// Usado quando o cliente envia um arquivo e a legenda diz que é o comprovante
const TEXTO_COMPROVANTE = 'Recebi o seu comprovante! Em breve nossa equipe irá conferir o pagamento e dar sequência à sua reserva, tudo bem?';

// Motivos que primeiro PERGUNTAM ao cliente se ele quer falar com a equipe (os demais transferem direto)
const PEDEM_CONSENTIMENTO = ['sem_resposta', 'outro'];
const FRASE_CONSENTIMENTO = 'Quer que eu chame a nossa equipe';
const TEXTO_CONSENTIMENTO = 'Não encontrei essa informação por aqui. Quer que eu chame a nossa equipe para te ajudar?';
const TEXTO_SEGUIR = 'Tudo bem! Seguimos por aqui. Em que mais posso ajudar?';
const TEXTO_ENCERRAR = 'Sem problemas! Se precisar de qualquer coisa, é só me chamar por aqui.';

// Motivos exibidos no aviso interno da equipe
const MOTIVOS = {
  midia: 'Cliente enviou arquivo, imagem ou áudio',
  pagamento: 'Pagamento / comprovante',
  cartao: 'Cliente quer pagar no cartão',
  pedido_do_cliente: 'Cliente pediu para falar com atendente',
  reclamacao: 'Reclamação, cancelamento ou reembolso',
  sem_resposta: 'Dúvida que o assistente não soube responder',
  falha: 'Falha técnica: a resposta automática não saiu',
  outro: 'Outro motivo'
};
// Motivos que apenas AVISAM a equipe, sem pausar o assistente na conversa
const SEM_PAUSA = ['falha'];
// =============================================

const base = $('Extrai dados da mensagem').first().json;
// Se o cliente mandou áudio e ele foi transcrito, usa o texto transcrito como mensagem
let efetiva = null;
try { efetiva = $('Mensagem para responder').first()?.json || null; } catch (e) { efetiva = null; }
const dados = efetiva ? { ...base, message: efetiva.message, hasMedia: efetiva.viaAudio ? false : base.hasMedia } : base;
let guardaValor = '';
let usouReserva = '';
let diagnosticoAudio = '';
const MOSTRAR_DIAGNOSTICO_NO_AVISO = false; // desligado: o áudio já funciona (troque para true só para investigar falhas de áudio)
if (dados.hasMedia && /audio|ptt/i.test(String(base.mediaType) + ' ' + String(base.mediaMime))) {
  const get = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
  const pa = get('Prepara áudio');
  if (!pa) diagnosticoAudio = 'passou direto: o nó "Prepara áudio" não executou (fluxo antigo ativo?) | mediaUrl=' + base.mediaUrl + ' | mediaMime=' + base.mediaMime;
  else if (!pa.audio_ok) diagnosticoAudio = 'URL ou tipo recusados | mediaUrl=' + base.mediaUrl + ' | mediaMime=' + base.mediaMime + ' | session=' + base.session;
  else if (!get('Prepara transcrição')) diagnosticoAudio = 'falha ao baixar o áudio do WAHA (nó "Baixa áudio")';
  else if (get('Prepara transcrição').ok !== true) diagnosticoAudio = 'áudio vazio, acima de 10 MB ou binário não lido';
  else { const t1 = get('Transcreve áudio'), t2 = get('Transcreve áudio (reserva)'), t3 = get('Transcreve áudio (Groq)'); diagnosticoAudio = 'transcrição falhou | principal: ' + JSON.stringify(t1 || {}).slice(0, 170) + ' | reserva: ' + JSON.stringify(t2 || {}).slice(0, 170) + ' | groq: ' + JSON.stringify(t3 || {}).slice(0, 170); }
}
if (diagnosticoAudio) diagnosticoAudio = 'evento=' + base.event + ' id=' + String(base.payload_id).slice(-14) + ' | ' + diagnosticoAudio;
const textoCliente = String(dados.message || '').trim();
const nome = String(dados.pushName || '').trim() || 'Cliente sem nome';

// Tipo da mídia (usado na resposta ao cliente e no aviso da equipe)
const mt = String(dados.mediaType || '').toLowerCase();
const tipoMidia = /image/.test(mt) ? 'imagem' : /video/.test(mt) ? 'vídeo' : /audio|ptt/.test(mt) ? 'áudio'
  : /document|pdf|application/.test(mt) ? 'documento' : 'arquivo, imagem ou áudio';
const SEU_TIPO = { 'imagem': 'a sua imagem', 'vídeo': 'o seu vídeo', 'áudio': 'o seu áudio', 'documento': 'o seu documento' };
const textoMidia = `Recebi ${SEU_TIPO[tipoMidia] || 'o seu arquivo'}! Vou avisar a nossa equipe de atendimento para analisar, e você receberá o retorno em breve, tudo bem?`;

function saida(reply, handoff, reason) {
  // pausar = a conversa passa para a equipe e o assistente fica em silêncio (exceto nos motivos de SEM_PAUSA)
  const pausar = !!handoff && !SEM_PAUSA.includes(reason);
  let ultima = textoCliente.slice(0, 200);
  if (dados.hasMedia) ultima = ultima ? ultima + ' [+ ' + tipoMidia + ']' : '[' + tipoMidia + ']';
  if (efetiva && efetiva.viaAudio) ultima = '[áudio transcrito] ' + ultima;
  const fmt = (ms) => Object.fromEntries(
    new Intl.DateTimeFormat('pt-BR', {
      timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit',
      hour: '2-digit', minute: '2-digit', hourCycle: 'h23'
    }).formatToParts(new Date(ms)).map(x => [x.type, x.value])
  );
  const agora = fmt(Date.now());
  const limite = fmt(Date.now() + HORAS_SEM_RESPOSTA * 60 * 60 * 1000);
  const horarioEnvio = `${agora.hour}:${agora.minute}`;
  const voltaEm = `${limite.day}/${limite.month} às ${limite.hour}:${limite.minute}`;
  const rodape = pausar
    ? `_Assistente pausado na conversa por 12h após a última mensagem da equipe (se ninguém responder, volta em ${voltaEm})._`
    : '_O assistente continua ativo nesta conversa. Se for urgente, responda o cliente diretamente._';
  const aviso = handoff
    ? [
        '🔔 *Cliente esperando por atendimento*',
        '',
        `*Cliente:* ${nome}`,
        `*Motivo:* ${MOTIVOS[reason] || MOTIVOS.outro}`,
        `*Última mensagem:* ${ultima}`,
        `*Horário de envio:* ${horarioEnvio}`,
        '',
        rodape
      ].concat(MOSTRAR_DIAGNOSTICO_NO_AVISO && diagnosticoAudio ? ['', '🛠 Diagnóstico técnico do áudio (temporário): ' + diagnosticoAudio.slice(0, 600)] : []).join('\n')
    : '';
  return [{ json: { reply, handoff, pausar, reason, aviso, equipeChatId: EQUIPE_CHAT_ID, guardaValor, diagnosticoAudio, usouReserva } }];
}

// Texto do cliente sem acento e em minúsculas, para as regras de segurança
const t = textoCliente.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
// Versão sem pontuação e sem espaços repetidos (para comparar respostas curtas como "sim, por favor!")
const tl = t.replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const RESPOSTAS_SIM = /^(sim+|s|pode|pode sim|pode chamar|pode chamar sim|pode ser|quero|quero sim|claro|claro que sim|com certeza|por favor|sim por favor|sim pode|isso|isso mesmo|aham|uhum|ok+|okay|chama|chama sim|chame)$/;
const RESPOSTAS_NAO = /^(nao+|n|nao precisa|agora nao|nao obrigad[oa]|nao quero|nao quero nao|deixa|deixa pra la|dispenso)$/;
// Cliente encerrando a conversa ("não quero mais informações", "só isso", "obrigado")
const encerra = /\b(nao quero mais (informacoes?|nada)|nao preciso mais|so isso|era so isso|ja resolvi|ja resolveu|pode encerrar|tchau|ate mais|ate logo)\b/.test(t)
  || /^(obrigad[oa]|muito obrigad[oa]|valeu|show|beleza|blz|ok obrigad[oa])$/.test(tl);
// Cliente avisa que JÁ pagou ("ainda não paguei" não conta)
const jaPagou = /\b(ja paguei|paguei|fiz o pix|fiz o pagamento|fiz a transferencia|pix feito|pix realizado|pagamento feito|pagamento realizado|efetuei o pagamento|enviei o comprovante|segue o comprovante|segue comprovante)\b/.test(t)
  && !/\bnao (paguei|fiz|efetuei|enviei)\b/.test(t);
// Cliente ESCOLHE pagar no cartão. Perguntas e dúvidas ("pode ser no cartão?", "queria saber se posso pagar no cartão",
// "gostaria de saber se aceita cartão") NÃO contam: nesses casos o assistente responde sozinho.
const perguntaSobreCartao = /\?/.test(t)
  || /\b(saber|aceita|aceitam|aceito|posso|podemos|podem|da pra|da para|tem como|e possivel|como (faco|funciona|pago)|qual|quais|quanto|taxa|taxas|juros)\b/.test(t);
const escolheCartao = (/\b(quero|queria|vou|prefiro|gostaria de|vai ser|vou querer)\b[^?]{0,20}\bcartao\b/.test(t)
  && !/\bnao (quero|vou|prefiro|gostaria|queria)\b[^?]{0,20}\bcartao\b/.test(t)
  && !perguntaSobreCartao)
  || /^(no |de |em )?cartao( de credito)?$/.test(tl) && !/\?/.test(t);   // resposta curta: "cartão", "no cartão"
// Cliente PEDE uma pessoa. A palavra "atendente" sozinha não conta ("vocês têm atendente no domingo?", "o atendente foi ótimo").
const pedeHumano = /\b(pessoa de verdade|atendimento humano|(quero|preciso|prefiro|gostaria|pode chamar|podem chamar|chama|chame|passa|passe)( de| pra| para| com)?( um| uma| o| a)? (humano|atendente|pessoa|alguem)|falar com (uma |um |o |a )?(pessoa|alguem|atendente|humano|responsavel))\b/.test(t)
  && !/\bnao (quero|preciso|precisa|vou)\b[^?]{0,20}\b(atendente|humano|pessoa|alguem)\b/.test(t);

// 1) Mídia (imagem, PDF, áudio, vídeo...) ou mensagem sem texto: transfere direto, sem chamar o Gemini
if (dados.hasMedia) {
  if (jaPagou) return saida(TEXTO_COMPROVANTE, true, 'pagamento');
  return saida(textoMidia, true, 'midia');
}

// 1a) Só agradecimento ou despedida: responde sem chamar o Gemini
const CORTESIA = /^(((ok|certo|perfeito|combinado) )?((muito|mto) )?(obrigad[oa]s?|agradecid[oa]|agradeco)( (demais|mesmo|pela atencao|pelas informacoes|pelo retorno|pela ajuda))?|(ate mais|ate logo|ate a proxima|ate breve))$/;
if (CORTESIA.test(tl)) {
  const despedida = /^ate\b/.test(tl);
  const opcoes = despedida
    ? ['Até mais! Qualquer dúvida, é só chamar por aqui.',
       'Até logo! Estamos por aqui quando precisar.',
       'Até a próxima! Se surgir qualquer dúvida, é só chamar.']
    : ['Por nada! Se surgir mais alguma dúvida, é só me chamar por aqui.',
       'Foi um prazer ajudar! Qualquer dúvida, estou por aqui.',
       'Disponha! Se precisar de algo mais, é só chamar.',
       'De nada! Fico à disposição por aqui.'];
  return saida(opcoes[Math.floor(Math.random() * opcoes.length)], false, '');
}

// 1b) Histórico (lido uma vez) e verificação de uma pergunta de consentimento pendente
let historico = '';
let historicoOk = true;
try {
  historico = String($('Busca histórico do cliente').first()?.json?.history_text || '');
} catch (e) {
  historicoOk = false;
}
let consentimentoPendente = false;
let msgPendente = '';
{
  const mensagens = historico.split(/\n(?=(?:Cliente|OVERTRIP|Atendente \(equipe\)): )/);
  for (let i = mensagens.length - 1; i >= 0; i--) {
    if (mensagens[i].startsWith('Cliente: ')) continue;          // pula mensagens seguidas do cliente
    consentimentoPendente = mensagens[i].startsWith('OVERTRIP: ') && mensagens[i].includes(FRASE_CONSENTIMENTO);
    msgPendente = mensagens[i];
    break;
  }
}
if (consentimentoPendente && RESPOSTAS_SIM.test(tl)) {
  // se a pergunta pendente era sobre enviar o link do cartão, o motivo é "cartao"
  if (/link de pagamento/i.test(msgPendente)) return saida(TEXTOS.cartao, true, 'cartao');
  return saida(TEXTOS.sem_resposta, true, 'sem_resposta');
}
if (consentimentoPendente && RESPOSTAS_NAO.test(tl)) return saida(TEXTO_SEGUIR, false, '');

// ===== FICHA DA TRIP (montada aqui para o formato sair sempre igual) =====
const MOSTRAR_ROTEIRO = true;   // bloco com embarque, saída, retorno e paradas
const DOCUMENTO_REGRA = 'Obrigatório apresentar documento original com foto para a reserva/viagem (normas da ANTT)';
const TEXTO_FICHA_JA_ENVIADA = 'Os detalhes estão na mensagem que te enviei acima. Quer que eu repita ou explique algum ponto?';
const norm = (x) => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const lerTrips = () => { try { return $('Agrupa trips do site').first()?.json?.trips || []; } catch (e) { return []; } };
const lerBase = () => { try { return $('Consulta base de conhecimento').first()?.json || {}; } catch (e) { return {}; } };

function montaFicha(t, kn) {
  const lista = (itens, marcador) => itens.map((x) => `${marcador} ${x}`).join('\n');
  const bloco = (titulo, corpo) => `${titulo}\n\n${corpo}`;
  const arr = (v) => (Array.isArray(v) ? v.filter(Boolean) : []);
  const partes = [];

  // título
  const data = String(t.dateDisplay || '').trim();
  const cab = String(t.headlineDisplay || '').trim() || (data ? `${t.title} | ${data.toUpperCase()}` : t.title);
  partes.push(`*${cab}*`);

  // valor, entrada e formas de pagamento (trips gratuitas não têm)
  if (t.free !== true) {
    const linhas = [];
    const preco = String(t.priceDisplay || '').replace(/R\$\s+/, 'R$');
    if (preco) linhas.push(`💸 Valor por pessoa: ${preco}`);
    linhas.push(`🎟️ Garanta sua vaga com ${kn.reservation?.depositPercentage || 50}% de entrada.`);
    const parcelas = kn.reservation?.cardPayment?.installments;
    linhas.push(`💳 Formas de pagamento: ${parcelas ? `PIX e Cartão de Crédito ${parcelas} (com acréscimos da maquineta/link)` : 'PIX e cartão'}.`);
    partes.push(linhas.join('\n'));
  }

  // incluso
  let incluso = arr(t.includedServices);
  if (!incluso.length && t.includesHighlight) {
    incluso = String(t.includesHighlight).replace(/^Inclui\s+/i, '').replace(/\.$/, '').split(/,\s*|\s+e\s+(?=[^,]+$)/).map((x) => x.trim()).filter(Boolean);
  }
  if (incluso.length) partes.push(bloco('✅ *Incluso na experiência:*', lista(incluso, '🔸')));

  // roteiro (embarque, saída, retorno e paradas)
  if (MOSTRAR_ROTEIRO) {
    const l = [];
    const emb = t.meetingDetails || t.meetingInfo || [t.meetingPoint, t.meetingCity].filter(Boolean).join(' - ');
    if (emb) l.push(`📍 Embarque: ${emb}`);
    if (t.departureTime) l.push(`⏰ Saída às ${t.departureTime}${t.departureTolerance ? ` (+${t.departureTolerance} de tolerância)` : ''}`);
    if (t.returnTime) l.push(`🏁 Retorno previsto às ${t.returnTime}`);
    l.push(...arr(t.routeNotes));
    if (l.length) partes.push(bloco('🗺️ *ROTEIRO:*', l.join('\n')));
  }

  // etapas (lista sem título)
  const etapas = arr(t.itinerary).length ? arr(t.itinerary) : arr(t.includes);
  if (etapas.length) partes.push(lista(etapas, '🔸'));

  // informações da trilha
  const nivel = String(t.intensityClass || '').toLowerCase() || String(t.intensityLabel || '').replace(/^Intensidade\s+/i, '').toLowerCase();
  const trilha = [];
  if (t.trailDistance) trilha.push(`🔸 Percurso: ${t.trailDistance}`);
  if (nivel) trilha.push(`🔸 Nível: ${nivel}`);
  if (trilha.length) partes.push(bloco('🥾 *INFORMAÇÕES DA TRILHA*', trilha.join('\n')));

  // ponto de apoio
  const apoio = [t.supportPoint ? `📍 ${t.supportPoint}` : '', t.supportPointInfo || ''].filter(Boolean);
  if (apoio.length) partes.push(bloco('🍲 *PONTO DE APOIO*', apoio.join('\n\n')));

  // informações importantes (com a regra geral do documento)
  const importantes = arr(t.importantInfo);
  if (kn.documents && !importantes.some((x) => /documento/i.test(x))) importantes.push(DOCUMENTO_REGRA);
  if (importantes.length) partes.push(bloco('⚠️ *INFORMAÇÕES IMPORTANTES:*', lista(importantes, '*')));

  partes.push(t.free === true ? 'Quer participar?' : 'Quer garantir sua vaga?');
  return partes.join('\n\n');
}

// 2) Resposta do Gemini + marcação de transferência [[HUMANO:motivo]]
//    Se o Gemini falhar, o item chega vazio e cai na proteção do passo 4.
let bruto = '';
try {
  bruto = String($('Valida resposta principal').first()?.json?.texto || '');
} catch (e) {
  bruto = '';
}
// Se o modelo principal falhou, usa a resposta do 1º ou do 2º modelo de reserva (nodes "Obtém resposta da reserva 1/2")
if (!bruto.trim()) {
  for (const [nodeName, rotulo] of [['Obtém resposta da reserva 1', 'reserva 1'], ['Obtém resposta Qwen', 'Qwen Oracle']]) {
    try {
      const x = String($(nodeName).first()?.json?.texto || '');
      if (x.trim()) { bruto = x; usouReserva = rotulo; break; }
    } catch (e) {}
  }
}
const marca = bruto.match(/\[\[?\s*HUMANO\s*(?::\s*([a-z_]+))?\s*\]{0,2}/i);
const marcaFicha = bruto.match(/\[\[\s*FICHA\s*(?::\s*([^\]]*?))?\s*\]\]/i);
let reply = bruto.replace(/\[\[?\s*HUMANO[^\]\n]*\]{0,2}/gi, '').replace(/\[\[[^\]]*\]\]/g, '').trim();

let handoff = false;
let reason = '';
const razaoMarca = marca ? (TEXTOS[String(marca[1] || 'outro').toLowerCase()] ? String(marca[1] || 'outro').toLowerCase() : 'outro') : '';
// "falha" nunca vem do modelo: é um motivo interno (impede que o cliente force uma transferência sem pausa)
const razaoMarcaSegura = razaoMarca === 'falha' ? 'outro' : razaoMarca;
const cartaoSemEscolhaClara = marca && razaoMarcaSegura === 'cartao' && !escolheCartao && !jaPagou && !pedeHumano;
if (cartaoSemEscolhaClara) {
  // O modelo marcou "cartao", mas a frase é dúvida ou escolha incerta (ex.: "pode ser no cartão"): responde e confirma antes de transferir.
  // A frase "Quer que eu chame a nossa equipe" faz o "sim" seguinte virar transferência com motivo cartao.
  const parcelas = String(lerBase().reservation?.cardPayment?.installments || '').trim();
  reply = `Aceitamos cartão de crédito${parcelas ? ' ' + parcelas : ''}, com acréscimos da maquineta/link. Quer que eu chame a nossa equipe para enviar o link de pagamento?`;
} else if (marca && !PEDEM_CONSENTIMENTO.includes(razaoMarcaSegura)) {
  handoff = true; reason = razaoMarcaSegura;        // pagamento, cartao, pedido_do_cliente, reclamacao
} else if (jaPagou) {                               // rede de segurança: o Gemini esqueceu a marcação
  handoff = true; reason = 'pagamento'; reply = TEXTOS.pagamento;
} else if (escolheCartao) {                         // rede de segurança: cliente escolheu o cartão (o time cuida)
  handoff = true; reason = 'cartao'; reply = TEXTOS.cartao;
} else if (pedeHumano) {                            // rede de segurança: cliente pediu uma pessoa
  handoff = true; reason = 'pedido_do_cliente'; reply = TEXTOS.pedido_do_cliente;
} else if (marca) {                                 // sem_resposta / outro: pergunta antes de transferir
  reply = encerra ? TEXTO_ENCERRAR : TEXTO_CONSENTIMENTO;
}

// 2b) Anotações internas do histórico ("[mídia recebida]", "[mídia enviada]") nunca vão para o cliente
const ANOTACAO = /\[\s*m[ií]dia\s+(recebida|enviada)[^\]]*\]/i;
if (ANOTACAO.test(reply)) {
  reply = reply.replace(new RegExp(ANOTACAO.source, 'gi'), '').trim();
  if (!reply && !handoff) reply = TEXTO_SEM_MIDIA;
}

// 2c) Ficha da trip: o modelo só pede ([[FICHA:título]]) e o texto é montado aqui
if (marcaFicha && !handoff) {
  const trips = lerTrips();
  const kn = lerBase();
  const pedido = norm(marcaFicha[1]);
  const abertas = trips.filter((t) => t.status === 'open');
  const casa = (t) => pedido && (norm(t.title) === pedido || norm(t.title).includes(pedido) || pedido.includes(norm(t.title)));
  const encerrada = trips.find((t) => t.status !== 'open' && casa(t));
  let trip = abertas.find((t) => norm(t.title) === pedido) || abertas.find(casa);
  if (!trip && !encerrada && abertas.length === 1) trip = abertas[0];
  if (trip) {
    const cab = String(trip.headlineDisplay || '').trim();
    reply = cab && historico.includes(cab) ? TEXTO_FICHA_JA_ENVIADA : montaFicha(trip, kn);
  } else if (encerrada) {
    reply = abertas.length === 1
      ? `A ${encerrada.title} já foi realizada. No momento temos a ${abertas[0].title} com vagas abertas. Quer saber os detalhes?`
      : `A ${encerrada.title} já foi realizada. Quer que eu te conte sobre as próximas viagens?`;
  } else if (abertas.length > 1) {
    reply = `No momento temos estas experiências abertas: ${abertas.map((t) => t.title).join(' e ')}. Qual delas você quer conhecer?`;
  } else if (!reply) {
    reply = 'Não encontrei essa experiência aberta no momento. Quer que eu te conte sobre as próximas viagens?';
  }
}

// 3) Sem transferência, a frase de transferência não pode aparecer (evita prometer algo que não vai acontecer)
if (!handoff) {
  reply = reply.replace(/\s*Em (alguns instantes|breve) nossa equipe ir[aá] prosseguir com (o )?seu atendimento,? tudo bem\?/gi, '').trim();
}

// 3b) GUARDA DE VALORES: nenhum "R$" na resposta pode ser diferente dos valores das fontes (trips e base de conhecimento)
{
  const RE_MOEDA = /R\$\s*(\d{1,3}(?:\.\d{3})+|\d+)(?:[,.](\d{1,2}))?/g;
  const RE_REAIS = /(\d{1,3}(?:\.\d{3})+|\d+)(?:[,.](\d{1,2}))?\s*reais/gi;
  const centavos = (i, f) => parseInt(String(i).replace(/\./g, ''), 10) * 100 + (f ? parseInt(String(f).padEnd(2, '0'), 10) : 0);
  const achar = (texto) => {
    const r = [];
    for (const m of String(texto).matchAll(RE_MOEDA)) r.push(centavos(m[1], m[2]));
    for (const m of String(texto).matchAll(RE_REAIS)) r.push(centavos(m[1], m[2]));
    return r.filter((x) => x > 0);
  };
  const noReply = achar(reply);
  if (noReply.length) {
    let fontes = {};
    try { fontes = { trips: lerTrips(), base: lerBase() }; } catch (e) { fontes = {}; }
    const base = new Set(achar(JSON.stringify(fontes)));
    const CHAVE_VALOR = /pre[cç]o|price|valor|amount|deposit|entrada|restante|remaining|fee|taxa/i;
    const CHAVE_NAO = /percent|pct|parcel|install|max|min|count|qtd/i;
    const varre = (o) => {
      if (Array.isArray(o)) { o.forEach(varre); return; }
      if (o && typeof o === 'object') {
        for (const [k, v] of Object.entries(o)) {
          if (typeof v === 'number' && CHAVE_VALOR.test(k) && !CHAVE_NAO.test(k) && v > 0) base.add(Math.round(v * 100));
          else varre(v);
        }
      }
    };
    varre(fontes);
    const bases = [...base];
    const metades = bases.flatMap((c) => [Math.floor(c / 2), Math.ceil(c / 2)]);
    const permitidos = new Set();
    for (const c of new Set([...bases, ...metades])) for (let k = 1; k <= 15; k++) permitidos.add(c * k);
    for (const a of bases) for (const b of bases) permitidos.add(a + b);
    const ok = (c) => permitidos.has(c) || permitidos.has(c - 1) || permitidos.has(c + 1);
    const invalidos = noReply.filter((c) => !ok(c));
    if (invalidos.length) {
      guardaValor = 'valores não encontrados nas fontes: ' + invalidos.map((c) => (c / 100).toFixed(2)).join(', ');
      reply = handoff ? (TEXTOS[reason] || TEXTOS.outro) : TEXTO_CONSENTIMENTO;
    }
  }
}

// 4) Resposta vazia (falha do Gemini): avisa o cliente e AVISA a equipe, mas sem pausar o assistente
//    (motivo "falha" está em SEM_PAUSA: o bot continua ativo para a próxima mensagem do cliente)
if (!reply) {
  handoff = true;
  if (!reason) reason = 'falha';
  reply = TEXTOS[reason] || TEXTOS.outro;
}

// 5) Primeiro contato: garante a saudação e a apresentação (o modelo costuma cumprimentar, mas nem sempre se apresenta)
const primeiroContato = historicoOk && !historico.trim();
if (primeiroContato && reply && !/assistente virtual/i.test(reply)) {
  const hora = parseInt(new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', hourCycle: 'h23' }).format(new Date()), 10);
  const periodo = hora < 12 ? 'bom dia' : hora < 18 ? 'boa tarde' : 'boa noite';
  // usa o primeiro nome só se parecer um nome de pessoa (evita emojis e apelidos)
  const bruto1 = nome.split(/\s+/)[0];
  const usaNome = /^[A-Za-zÀ-ÿ'’-]{2,20}$/.test(bruto1) && bruto1 !== 'Cliente';
  const primeiroNome = usaNome ? bruto1.charAt(0).toUpperCase() + bruto1.slice(1).toLowerCase() : '';
  const saudacao = `Olá, ${periodo}${primeiroNome ? ', ' + primeiroNome : ''}! Eu sou a assistente virtual da OVERTRIP.`;
  // tira a saudação solta do começo da resposta do modelo, para não duplicar
  let corpo = reply.replace(/^\s*(?:(?:ol[aá]|oi+|ei)(?=[\s,!.?]|$)[\s,!.]*)?(?:(?:bom dia|boa tarde|boa noite)(?=[\s,!.?]|$)[\s,!.]*)?(?:tudo (?:bem|certo)\??[\s,!.]*)?/i, '');
  if (primeiroNome) corpo = corpo.replace(new RegExp('^' + primeiroNome + '(?=[\\s,!.?]|$)[\\s,!.]*', 'i'), '');
  corpo = corpo.trim();
  reply = `${saudacao}\n\n${corpo || reply}`;
}

return saida(reply, handoff, reason);

